def parse_cells(cells, skip_first_n=0):
    """按11列解析，可跳过前N个cell"""
    rows = []
    for i in range(skip_first_n, len(cells), 11):
        chunk = cells[i:i+11]
        if len(chunk) < 11:
            break
        row = {}
        for j, h in enumerate(HEADERS):
            row[h] = chunk[j] if j < len(chunk) else ''
        if any(row[h] for h in HEADERS if h != '消耗'):
            rows.append(row)
    return rows

def main():
    page1 = json.loads(PAGE1_CELLS_STR)
    page2 = json.loads(PAGE2_CELLS_STR)
    
    # Page1: 前11格是汇总行，跳过
    rows1 = parse_cells(page1, skip_first_n=11)
    # Page2: 没有汇总行
    rows2 = parse_cells(page2, skip_first_n=0)
    
    all_rows = rows1 + rows2
    print(f'解析记录数: page1={len(rows1)}, page2={len(rows2)}, total={len(all_rows)}')
    
    # 筛选消耗>2000
    over = []
    for r in all_rows:
        try:
            cost = float(r['消耗'].replace(',', '').strip())
            if cost > 2000:
                r['_cost_num'] = cost
                over.append(r)
        except ValueError:
            pass
    
    over.sort(key=lambda x: x['_cost_num'], reverse=True)
    print(f'消耗>2000的记录: {len(over)}条')
    for r in over:
        print(f'  - {r["抖音号昵称"]}: {r["消耗"]}')
    
    if not over:
        print('NO_OVER_2000')
        return
    
    # 保存CSV
    now = datetime.now()
    date_str = now.strftime('%Y-%m-%d')
    time_str = now.strftime('%H-%M')
    stat_time = now.strftime('%Y-%m-%d %H:%M')
    csv_path = f'/workspace/star_report_cost_over_2000_{date_str}_{time_str}.csv'
    
    with open(csv_path, 'w', newline='', encoding='utf-8-sig') as f:
        w = csv.DictWriter(f, fieldnames=HEADERS)
        w.writeheader()
        for r in over:
            clean = {k: v for k, v in r.items() if not k.startswith('_')}
            w.writerow(clean)
    print(f'CSV_PATH: {csv_path}')
    
    # 构建Markdown消息
    lines = []
    lines.append('## 【消耗预警】星广报表实时消耗>2000')
    lines.append(f'统计时间：{stat_time}')
    lines.append('')
    lines.append('| 抖音号昵称 | 标题 | 消耗 | 视频链接 | 日期 |')
    lines.append('|-----------|------|------|---------|------|')
    for r in over:
        nickname = r.get('抖音号昵称', '').replace('|', '\\|')
        title = r.get('标题', '').replace('|', '\\|')
        if len(title) > 50:
            title = title[:50] + '...'
        cost = r.get('消耗', '')
        video_url = r.get('视频播放链接', '').strip('"').strip("'")
        date = r.get('数据统计日期', '')
        link_md = f'[观看]({video_url})' if video_url else ''
        lines.append(f'| {nickname} | {title} | {cost} | {link_md} | {date} |')
    lines.append('')
    lines.append(f'共{len(over)}条记录消耗超过2000元')
    md_msg = '\n'.join(lines)
    
    md_path = f'/workspace/star_report_message_{date_str}_{time_str}.txt'
    with open(md_path, 'w', encoding='utf-8') as f:
        f.write(md_msg)
    print(f'MARKDOWN_PATH: {md_path}')
    print('---MARKDOWN_PREVIEW_START---')
    print(md_msg)
    print('---MARKDOWN_PREVIEW_END---')

if __name__ == '__main__':
    main()
